import{newMap,uid}from'./model.js';import{addPortal}from'./world-model.js';
// A building owns one coherent native floor family, never a random room per level.
export function createDepartmentStore(exterior,footprint,library,familyId,{name='Department store',binding=()=>({generated:true,sourceId:null,interiorKind:'department-store',mapType:8,originalWidth:0,originalHeight:0,originalBlocks:[]}),ownerId=null,ownerType='assembly'}={}){
 const family=library.departmentStores?.find(f=>f.id===familyId)||library.departmentStores?.[0];if(!family)throw Error('The matching department-store floors are not included.');const maps=family.floors.map((f,i)=>{const m=newMap(name+' · '+f.label,f.width,f.height);m.rom=binding(family,f);m.movement=structuredClone(f.movement);m.world={x:(exterior.world?.x||0)+300+i%3*280,y:(exterior.world?.y||0)+Math.floor(i/3)*340};m.generator={type:'interior',version:3,kind:'department-store',exteriorId:exterior.id,storeFamily:family.id,storeFloor:i,sourceRoom:f.key,buildingId:ownerId};for(let y=0;y<f.height;y++)for(let x=0;x<f.width;x++)m.layers.ground[y*f.width+x]={a:f.assetId,sx:x*16,sy:y*16,size:16};return m;}),project={maps:[exterior,...maps],links:[]},points=footprint.entrances||[],exits=family.floors[0].warps.filter(w=>w.role==='exit'),done=new Set();
 const link=(from,to,twoWay,label)=>addPortal(project,from,to,{twoWay,label,style:'step'}),tag=(l,end,e)=>{if(ownerId){l[ownerType==='building'?'buildingId':'assemblyId']=ownerId;l.buildingEnd=end;l.buildingEntrance={...e};l.buildingDoorIndex=Math.max(0,points.findIndex(p=>p.x===e.x));}};
 for(let i=0;i<points.length;i++){const e=points[i],w=exits.find(w=>w.index===e.warp)||exits[Math.min(i,exits.length-1)];if(!w)throw Error('The ground floor has no exterior entrance.');const l=link({mapId:exterior.id,x:footprint.x+e.x,y:footprint.y+e.y},{mapId:maps[0].id,x:w.x,y:w.y},true,name+' · door '+(i+1));tag(l,'from',e);done.add('0:'+w.index);}
 // Native wide exits have side cells too; all return to their nearest street door.
 for(const w of exits){if(done.has('0:'+w.index))continue;const e=points.reduce((best,e)=>{const anchor=exits.find(w=>w.index===e.warp)||exits[0],b=exits.find(w=>w.index===best?.warp)||exits[0];return Math.abs(anchor.x-w.x)<Math.abs(b.x-w.x)?e:best;},points[0]);if(!e)continue;const l=link({mapId:maps[0].id,x:w.x,y:w.y},{mapId:exterior.id,x:footprint.x+e.x,y:Math.min(exterior.height-1,footprint.y+e.y+1)},false,name+' · exit');tag(l,'to',{x:e.x,y:e.y+1});}
 for(let i=0;i<family.floors.length;i++)for(const w of family.floors[i].warps){if(w.role==='stairs'){const j=family.floors.findIndex(f=>f.key===w.target),to=family.floors[j]?.warps.find(v=>v.index===w.warp);if(j<0||!to)continue;const token=[i+':'+w.index,j+':'+to.index].sort().join('/');if(done.has(token))continue;done.add(token);link({mapId:maps[i].id,x:w.x,y:w.y},{mapId:maps[j].id,x:to.x,y:to.y},true,name+' · '+family.floors[i].label+' ↔ '+family.floors[j].label);}else if(w.role==='elevator'){maps[i].markers.push({id:uid(),kind:'sign',title:'Lift notice',x:w.x,y:w.y,text:'Please use the stairs to reach the other floors.',runtime:{action:'sequence',enabled:true,trigger:'interact',steps:[{type:'say',text:'Please use the stairs to reach the other floors.'}]}});}}
 return{maps,links:project.links,assets:family.floors.map(f=>library.assets.find(a=>a.id===f.assetId)),family,ground:maps[0]};
}
export function attachDepartmentStore(project,exterior,object,template,plan,library,{sourceId=null,reader=null}={}){
 const source=template.entrances||[template.entrance],entrances=source.map(e=>({x:Math.max(0,plan.columns.indexOf(e.x)),y:Math.max(0,plan.rows.indexOf(e.y)),warp:e.x===6?4:1})),bundle=createDepartmentStore(exterior,{x:object.x,y:object.y,entrances},library,template.departmentFamily,{name:object.name,ownerId:object.id,ownerType:'building',binding:(family,f)=>({generated:true,sourceId,interiorKind:'department-store',mapType:8,originalWidth:0,originalHeight:0,originalBlocks:[],...(reader&&sourceId===family.sourceId?{templateKey:f.key}:{})})});
 if(project.maps.length+bundle.maps.length>80||project.maps.reduce((n,m)=>n+m.width*m.height,0)+bundle.maps.reduce((n,m)=>n+m.width*m.height,0)>400000)throw Error('These store floors exceed the project map or tile limit.');const assets=bundle.assets.filter(a=>!project.assets.some(v=>v.id===a.id));if(project.assets.length+assets.length>512)throw Error('These store floors exceed the project image limit.');project.assets.push(...assets);project.maps.push(...bundle.maps);project.links.push(...bundle.links);object.building.interiorId=bundle.ground.id;object.building.floorIds=bundle.maps.map(m=>m.id);object.collisionChoice='mask';object.collisionMask=Array.from({length:object.h},(_,y)=>Array.from({length:object.w},(_,x)=>entrances.some(e=>e.x===x&&y>=e.y)?0:1));return bundle.ground;
}

export function fitDepartmentDoors(object,template,plan,links){const doors=(template.entrances||[template.entrance]).map(e=>({x:Math.max(0,plan.columns.indexOf(e.x)),y:Math.max(0,plan.rows.indexOf(e.y))}));object.collisionChoice='mask';object.collisionMask=Array.from({length:object.h},(_,y)=>Array.from({length:object.w},(_,x)=>doors.some(e=>e.x===x&&y>=e.y)?0:1));for(const l of links.filter(l=>l.buildingId===object.id)){const e=doors[l.buildingDoorIndex||0];l.buildingEntrance={x:e.x,y:e.y+(l.buildingEnd==='to'?1:0)};}return doors;}
